#!/usr/bin/env python3
"""Generate TypedDicts describing the values an app renders with, from its questions.yaml and ix_values.yaml.

Mirrors how middleware builds the values (plugins/apps/schema_construction_utils.py):
- a key with `required` or a `default` is always present, any other key, or one with a `show_if`, is NotRequired
- `null: true` adds `| None`, `enum` becomes a Literal, `attrs` a nested TypedDict, `items` a list of the item type
Validation-only keys (min, max, private, $ref, ...) don't change the shape and are ignored.
The functional TypedDict syntax is used because questions have variables named like keywords (from, items, ...).
The TypedDicts are closed (PEP 728): no keys beyond the questions. For the lib to accept them, its parameters must be
read-only views: Mapping/Sequence instead of dict/list, and ReadOnly fields in its own TypedDicts (PEP 705).
"""

import json
import sys
from pathlib import Path
from typing import Any

import yaml

STRING_TYPES = {"string", "text", "hostpath", "path", "uri", "ipaddr"}
SCALAR_TYPES = {"int": "int", "boolean": "bool"}

# What middleware and CI add next to the user's values
HEADER = '''"""Generated by .github/scripts/values_types.py from questions.yaml and ix_values.yaml. Do not edit."""

from typing import Any, Literal, NotRequired

from typing_extensions import TypedDict

Image = TypedDict("Image", {"repository": str, "tag": str}, closed=True)
'''
CONTEXT_FIELDS = {
    "ix_context": "NotRequired[dict[str, Any]]",
    "ix_certificates": "NotRequired[dict[str, Any]]",
    "ix_volumes": "NotRequired[dict[str, Any]]",
    "ci": "NotRequired[bool]",
}


def literal(value: Any) -> str:
    """Python literal with double quoted strings, the way ruff formats them."""
    return json.dumps(value) if isinstance(value, str) else repr(value)


class Generator:
    def __init__(self) -> None:
        self.definitions: list[str] = []
        self.names: set[str] = set()

    def class_name(self, path: list[str]) -> str:
        base = "".join(part.title().replace("_", "").replace("-", "") for part in path) or "Values"
        name, counter = base, 2
        while name in self.names:
            name, counter = f"{base}{counter}", counter + 1
        self.names.add(name)
        return name

    def typed_dict(self, name: str, fields: dict[str, str]) -> str:
        body = "".join(f"        {literal(key)}: {value},\n" for key, value in fields.items())
        # closed: the keys are exactly the questions, so a lib TypedDict with extra ReadOnly NotRequired keys accepts it
        self.definitions.append(f"{name} = TypedDict(\n    {literal(name)},\n    {{\n{body}    }},\n    closed=True,\n)\n")
        return name

    def attr_fields(self, attrs: list[dict[str, Any]], path: list[str]) -> dict[str, str]:
        fields = {}
        for attr in attrs:
            schema = attr.get("schema", {})
            type_ = self.schema_type(schema, path + [attr["variable"]])
            # Middleware always builds a dict with attrs from its children's defaults
            declared = schema.get("required") or "default" in schema or (schema.get("type") == "dict" and schema.get("attrs"))
            always_present = declared and "show_if" not in schema
            fields[attr["variable"]] = type_ if always_present else f"NotRequired[{type_}]"
        return fields

    def schema_type(self, schema: dict[str, Any], path: list[str]) -> str:
        kind = schema.get("type")
        if "enum" in schema and schema["enum"]:
            type_ = f"Literal[{', '.join(literal(option['value']) for option in schema['enum'])}]"
        elif kind in STRING_TYPES:
            type_ = "str"
        elif kind in SCALAR_TYPES:
            type_ = SCALAR_TYPES[kind]
        elif kind == "dict":
            if attrs := schema.get("attrs"):
                type_ = self.typed_dict(self.class_name(path), self.attr_fields(attrs, path))
            else:
                type_ = "dict[str, Any]"
        elif kind == "list":
            items = [self.schema_type(item.get("schema", {}), path + ["item"]) for item in schema.get("items", [])]
            type_ = f"list[{' | '.join(dict.fromkeys(items)) or 'Any'}]"
        else:
            type_ = "Any"
        if schema.get("null"):
            type_ = f"{type_} | None"
        return type_

    def literal_type(self, value: Any, path: list[str]) -> str:
        """Type of a fixed ix_values.yaml value."""
        if isinstance(value, bool):
            return "bool"
        if isinstance(value, (int, float, str)):
            return type(value).__name__
        if isinstance(value, list):
            return f"list[{' | '.join(dict.fromkeys(self.literal_type(v, path) for v in value)) or 'Any'}]"
        if isinstance(value, dict):
            if path == ["images"]:
                return self.typed_dict(self.class_name(path), {key: "Image" for key in value})
            fields = {key: self.literal_type(v, path + [key]) for key, v in value.items()}
            return self.typed_dict(self.class_name(path), fields)
        return "Any"

    def generate(self, app_path: Path) -> str:
        questions = yaml.safe_load((app_path / "questions.yaml").read_text())["questions"]
        fields = self.attr_fields(questions, [])
        ix_values_path = app_path / "ix_values.yaml"
        ix_values = (yaml.safe_load(ix_values_path.read_text()) if ix_values_path.exists() else None) or {}
        # ix_values.yaml is merged over the user's values, so its keys win
        fields.update({key: self.literal_type(value, [key]) for key, value in ix_values.items()})
        fields.update({key: value for key, value in CONTEXT_FIELDS.items() if key not in fields})
        self.names.add("Values")
        self.typed_dict("Values", fields)
        return HEADER + "\n\n" + "\n\n".join(self.definitions)


def generate_values_types(app_path: Path) -> str:
    return Generator().generate(app_path)


def main() -> None:
    if len(sys.argv) != 2:
        sys.exit(f"Usage: {sys.argv[0]} <app_path>")
    sys.stdout.write(generate_values_types(Path(sys.argv[1])))


if __name__ == "__main__":
    main()
